(function(root){
'use strict';
const colours=['#eb9dcc','#8ddfca','#eac082','#91b9f2','#b5a0ec','#f58f98','#c5d5ed','#a8be8c'];
const num=n=>Number(n||0).toLocaleString('en-CA',{maximumFractionDigits:1});
const time=n=>{const seconds=Math.max(0,Math.floor(n+1e-7));return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');};
function el(tag,text,parent,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;parent?.append(e);return e;}
function svg(tag,attrs,parent){const e=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);parent?.append(e);return e;}
function render(host,r,details){
 const m=r.metrics,history=r.timeline||[],total=o=>Object.values(o).reduce((a,b)=>a+b,0),body=el('div',undefined,host,'report-body');
 const kpis=el('div',undefined,body,'report-kpis');
 for(const [label,value,sub] of [['TIME TOGETHER',time(r.time),'of a five-minute journey'],['HOSTILES DEFEATED',num(r.kills),num(m.created.monster)+' arrived'],['WAVES CLEARED',m.wavesCompleted+' / '+(r.plannedWaves??m.wavesStarted),'each threshold tells a story'],['AT THE FINAL MOMENT',num(r.buildings),'houses before the finale']]){const k=el('div',undefined,kpis);el('span',label,k);el('strong',value,k);el('small',sub,k);}
 const grid=el('div',undefined,body,'report-charts');
 function card(title,kicker,wide=false){const c=el('section',undefined,grid,'report-card'+(wide?' report-wide':''));el('small',kicker,c,'report-kicker');el('h2',title,c);return c;}
 const cursors=[];
 function lines(title,kicker,series){const c=card(title,kicker),legend=el('div',undefined,c,'chart-legend');series.forEach(([key,label],i)=>{const l=el('span',label,legend);l.style.setProperty('--series',colours[i]);});
 if(!history.length){el('p','No timeline recorded.',c);return;}
 const width=window.innerWidth<=700?320:600,right=width-16;const chart=svg('svg',{viewBox:'0 0 '+width+' 220',role:'img','aria-label':title},c);svg('title',{},chart).textContent=title+' over game time. Explore exact values with the timeline slider below.';
 const max=Math.max(1,...history.flatMap(p=>series.map(([key])=>p[key]||0))),duration=Math.max(1,r.time),x=t=>44+t/duration*(right-44),y=v=>180-v/max*145;
 for(let i=0;i<=3;i++){const v=max*i/3;svg('line',{x1:44,x2:right,y1:y(v),y2:y(v),class:'chart-grid'},chart);svg('text',{x:36,y:y(v)+4,'text-anchor':'end',class:'chart-axis'},chart).textContent=Intl.NumberFormat('en-CA',{notation:'compact',maximumFractionDigits:1}).format(v);}
 for(const t of [0,r.time/2,r.time])svg('text',{x:x(t),y:205,'text-anchor':'middle',class:'chart-axis'},chart).textContent=time(t);
 series.forEach(([key,label],i)=>{const points=history.map(p=>x(p.time)+','+y(p[key]||0)).join(' ');const area=svg('polygon',{points:x(history[0].time)+',180 '+points+' '+x(history.at(-1).time)+',180',fill:colours[i],opacity:'.055'},chart);svg('polyline',{points,fill:'none',stroke:colours[i],'stroke-width':2.5,'stroke-linejoin':'round','stroke-linecap':'round'},chart);if(history.length===1)svg('circle',{cx:x(history[0].time),cy:y(history[0][key]||0),r:3,fill:colours[i]},chart);});
 const cursor=svg('line',{x1:right,x2:right,y1:25,y2:180,class:'chart-cursor'},chart),readout=el('div',undefined,c,'chart-readout');cursors.push(p=>{cursor.setAttribute('x1',x(p.time));cursor.setAttribute('x2',x(p.time));readout.textContent=series.map(([key,label])=>label+' '+num(p[key])).join('  ·  ');});
 }
 lines('The pulse of the convoy','01 / HEALTH',[['hp','Remaining HP'],['maxHp','Maximum HP']]);
 lines('Life inside the circle','02 / POPULATION',[['soldiers','Soldiers'],['monsters','Hostiles'],['houses','Houses']]);
 lines('The price of staying','03 / CUMULATIVE DAMAGE',[['dealt','Dealt'],['taken','Taken']]);
 lines('Resistance over time','04 / CUMULATIVE KILLS',[['kills','Defeated']]);
 const scrub=el('section',undefined,grid,'report-card report-wide report-scrubber');const scrubLabel=el('label','EXPLORE YOUR JOURNEY',scrub);const slider=el('input',undefined,scrubLabel);slider.type='range';slider.min=0;slider.max=Math.max(0,history.length-1);slider.step=1;slider.value=slider.max;slider.disabled=!history.length;slider.setAttribute('aria-label','Explore run timeline');const stamp=el('output',undefined,scrub);const move=()=>{const p=history[Number(slider.value)];stamp.textContent=p?time(p.time):'No samples';if(p)cursors.forEach(fn=>fn(p));};slider.oninput=move;move();
 function bars(title,kicker,rows,unit=''){const c=card(title,kicker),max=Math.max(1,...rows.map(row=>row[1]));if(!rows.length)el('p','No data this run.',c,'report-empty');rows.forEach(([label,value],i)=>{const row=el('div',undefined,c,'report-bar');const heading=el('div',undefined,row);el('span',label,heading);el('b',num(value)+unit,heading);const track=el('div',undefined,row,'report-track');const fill=el('i',undefined,track);fill.style.width=Math.max(0,value/max*100)+'%';fill.style.background=colours[i%colours.length];});return c;}
 bars('Where the damage landed','05 / ACTUAL HP LOST',[['Locomotive',m.damage.train||0],['Carriages',m.damage.wagon||0],['Soldiers',m.damage.actor||0],['Houses',m.damage.building||0]],' HP');
 bars('Every shot counts','06 / FIREPOWER',[['Locomotive',m.shots.train||0],['Soldiers',m.shots.actor||0],['Hostiles',m.shots.monster||0]]);
 const survivors=card('What made it through','07 / SURVIVAL',true),rings=el('div',undefined,survivors,'report-rings');
 for(const [label,alive,created] of [['Soldiers',r.population.total,m.created.actor||0],['Carriages',r.wagons,m.created.wagon||0],['Houses',r.buildings,m.created.building||0]]){const block=el('div',undefined,rings),chart=svg('svg',{viewBox:'0 0 160 160',role:'img','aria-label':label+': '+alive+' of '+created+' survive'},block);svg('circle',{cx:80,cy:80,r:62,fill:'none',stroke:'#393347','stroke-width':9},chart);svg('circle',{cx:80,cy:80,r:62,fill:'none',stroke:colours[1],'stroke-width':9,'stroke-linecap':'round','stroke-dasharray':(created?Math.min(1,alive/created)*389.56:0)+' 389.56',transform:'rotate(-90 80 80)'},chart);svg('text',{x:80,y:83,'text-anchor':'middle',class:'ring-number'},chart).textContent=alive;svg('text',{x:80,y:106,'text-anchor':'middle',class:'chart-axis'},chart).textContent='OF '+created;el('b',label,block);el('small',num(m.lost[{Soldiers:'actor',Carriages:'wagon',Houses:'building'}[label]]||0)+' lost',block);}
 bars('The things outside','08 / DEFEATED BY TYPE',Object.entries(root.RoundCircleSimulation.types).map(([id,t])=>[t.name,m.killsByType[id]||0]));
 bars('Power you collected','09 / TOTAL MULTIPLIERS',Object.entries(r.bonuses).map(([id,v])=>[root.RoundCircleRewards.effects[id]||id,v]),'×');
 const waveCard=card('Every threshold crossed','10 / WAVE HISTORY',true);if(!r.waves?.length)el('p','No waves launched.',waveCard,'report-empty');for(const [i,w] of (r.waves||[]).entries()){const row=el('div',undefined,waveCard,'report-wave');el('span',String(i+1).padStart(2,'0'),row,'wave-number');el('b',w.name.replace(/^\d+\s*·\s*/,''),row);const track=el('div',undefined,row,'report-wave-track'),fill=el('i',undefined,track);const start=w.startedAt??0,end=w.completedAt??r.time;fill.style.left=Math.min(100,start/Math.max(1,r.time)*100)+'%';fill.style.width=Math.max(.5,(end-start)/Math.max(1,r.time)*100)+'%';fill.style.background=w.done?colours[1]:colours[0];el('span',w.done?'CLEARED':'OPEN',row,'wave-state');el('small',time(start)+' → '+(w.done?time(end):'end'),row);}
 const journey=card('The journey in numbers','11 / MOVEMENT & RECOVERY',true),facts=el('div',undefined,journey,'report-facts');for(const [v,label] of [[num(m.distance/(2*Math.PI*6.95)),'laps of the circle'],[num(r.collisions),'collisions'],[num(m.regenerated),'HP restored'],[num(m.boardings),'boardings'],[r.population.aboard+'/'+r.population.seats,'seats occupied'],[num(m.wagonsProduced),'carriages recruited']]){const f=el('div',undefined,facts);el('strong',v,f);el('small',label,f);}
 if(r.narrative?.choices?.length){const c=card('What you chose to call home','12 / YOUR WORDS',true);for(const choice of r.narrative.choices)el('blockquote',choice.text,c);}
 if(r.artifacts?.length){const c=card('Souvenirs of the circle','13 / ARTIFACTS',true),shelf=el('div',undefined,c,'report-artifacts');for(const b of r.artifacts){const item=el('div',undefined,shelf);el('span',b.icon,item);el('b',b.name,item);el('small','×'+num(b.factor),item);}}
 const exact=el('details',undefined,body,'report-exact');el('summary','All statistics · exact values',exact);const tables=el('div',undefined,exact,'endgame-grid');for(const [title,rows] of details){const c=el('section',undefined,tables);el('h2',title,c);const dl=el('dl',undefined,c);for(const [label,value] of rows){el('dt',label,dl);el('dd',typeof value==='number'?num(value):value,dl);}}
 el('p','Recorded in game time. Initial units and laboratory actions are included. Damage counts actual HP lost; survival compares remaining units with all units created. Wave bars run from launch to clear, or to the end of the run.',body,'report-method');
}
root.RoundCircleDashboard={render};
})(window);
